INSERT INTO ai_recommendations (id, match_id, title, description, severity, confidence, evidence, created_at, status) VALUES
    ('demo-rec-1', 'demo-match-5', 'Posible problema táctico: distancia excesiva entre la línea defensiva y el mediocampo', 'Revisar la distancia entre la línea defensiva y el mediocampo; considerar adelantar la línea de fondo o retrasar un mediocampista.', 'HIGH', 0.71, 'La distancia entre defensa y mediocampo promedió 0,26 (umbral 0,22) y lo superó en el 74 % de 120 cuadros.', '2026-10-11 19:06', 'GENERATED'),
    ('demo-rec-2', 'demo-match-5', 'Posible problema táctico: poca presión sobre el balón', 'Revisar la presión tras pérdida y el primer defensor; acercar al jugador más próximo al balón.', 'MEDIUM', 0.52, 'Sin el balón, el equipo tuvo en promedio 0,4 jugadores cerca del balón (umbral 0,5) y nadie lo presionó en el 63 % de 41 cuadros.', '2026-10-11 19:06', 'GENERATED'),
    ('demo-rec-3', 'demo-match-5', 'Posible problema táctico: baja compactación del equipo', 'Revisar la compactación sin balón; reducir el área ocupada acortando distancias entre líneas.', 'MEDIUM', 0.44, 'El área ocupada por el equipo promedió 0,27 de la imagen (umbral 0,25) en el 58 % de 120 cuadros.', '2026-10-11 19:06', 'REVIEWED'),
    ('demo-rec-4', 'demo-match-5', 'Posible problema táctico: desequilibrio numérico en una zona', 'Revisar la ocupación por tercios; equilibrar el número de jugadores donde el rival se carga.', 'LOW', 0.36, 'La mayor diferencia de jugadores entre equipos en un tercio fue 3,4 (umbral 3) en el 55 % de 120 cuadros.', '2026-10-11 19:06', 'GENERATED')
ON CONFLICT (id) DO NOTHING;
-- Team of each issue (migration 0011): the first three are about our team, the last one about the match
UPDATE ai_recommendations SET team = CASE WHEN id = 'demo-rec-4' THEN 'MATCH' ELSE 'TEAM_A' END
WHERE id IN ('demo-rec-1', 'demo-rec-2', 'demo-rec-3', 'demo-rec-4') AND team IS NULL;
